import {questionTopic} from './question-topics.js';
import {createUiState, uiContext, STAGES} from './ui-state.js';
const $=s=>document.querySelector(s);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function newRequestId(){const bytes=new Uint8Array(16);crypto.getRandomValues(bytes);return Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');}
const storage={get(key){try{return JSON.parse((key==='shift-session'?localStorage:sessionStorage).getItem(key));}catch{return null;}},set(key,value){try{(key==='shift-session'?localStorage:sessionStorage).setItem(key,JSON.stringify(value));}catch{notice('Storage is unavailable. Keep this tab open to retain your session.',true);}},remove(key){try{(key==='shift-session'?localStorage:sessionStorage).removeItem(key);}catch{}}};
let tabStorage;try{tabStorage=sessionStorage;}catch{tabStorage={getItem(){throw Error('Storage unavailable');},setItem(){throw Error('Storage unavailable');}};}
const ui=createUiState(tabStorage);
let optionalAi=false,focusVersion=0;
// Per-question opt-in is memory-only: never saved to browser storage.
let questionConsentKey=null;
function currentQuestionConsentKey(){const context=uiContext(state);if(!context)return null;const draft=ui.read(context);return JSON.stringify([context,draft.question,draft.questionTopic,currentInterview()?.messages.length??0]);}
function clearQuestionConsent(){questionConsentKey=null;const checkbox=document.getElementById('question-ai-consent');if(checkbox)checkbox.checked=false;}
function syncQuestionConsent(){if(questionConsentKey!==currentQuestionConsentKey())clearQuestionConsent();}

let session=storage.get('shift-session'),pending=storage.get('shift-pending'),state=null,cases=[],stage='analyse',search='',filter='all',sourceSearch='',dossierId=null,entryMode='create',selectedVote='',historyRound=null,busy=false,lastVersion=-1,confirmation=null,confirmationTrigger=null,lastHeartbeat=0;
const topicLabels={alibi:'Where were you at the time?',clue:'What did you notice?',motive:'What was at stake?',relationship:'How did you know the victim?'};
const phaseLabels={lobby:'Assembling the team',investigation:'Investigation in progress',accusation:'Make your accusation',reveal:'Timeline revealed'};
const stageLabels={analyse:'Analyse',interrogate:'Interrogate',deduce:'Deduce'};
const relationLabels={related:'May be connected',supports:'Supports',contradicts:'Contradicts'};
const portraitIds=new Set(['mara','ines','bento','celia','noa','rui','vera','davi','lia','tomas','helena','joel','olga','samira','elio']);
function person(id){return state?.suspects.find(s=>s.id===id);}
function currentInterview(){return state?.me.interviews.find(i=>i.round===state.round);}
function portraitUrl(id){return portraitIds.has(id)?`/assets/portraits/${id}.webp`:null;}
function avatar(s,large=false){const url=portraitUrl(s?.id);return `<span class="portrait ${large?'portrait-large':''}"><span class="portrait-fallback" aria-hidden="true">${esc(s?.initials||s?.name?.split(' ').map(x=>x[0]).slice(0,2).join('')||'?')}</span>${url?`<img src="${url}" alt="" width="512" height="512" loading="lazy" decoding="async">`:''}</span>`;}
function notice(message,error=false){const el=$('#notice');el.className=error?'error':'info';el.textContent=message;if(pending){const button=document.createElement?.('button');if(button){button.textContent='Retry safely';button.dataset.action='retry';el.append(button);}}}
function announce(message){$('#announcer').textContent=message;}
async function fetchJson(path,{body}={}){const response=await fetch(path,{method:body?'POST':'GET',credentials:'same-origin',headers:{...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(10000)});if(response.status===204)return null;const data=await response.json();if(!response.ok){const error=new Error(data.error??'This action could not be completed.');error.status=response.status;throw error;}return data;}
function storageNotice(){const el=$('#storage-notice');if(el)el.textContent=ui.persistent?'':'Draft storage is unavailable. Keep this tab open: unsent drafts will not survive a reload.';}
function saveDrafts(){if(!state)return;const context=uiContext(state);for(const el of document.querySelectorAll('[data-draft]')){const field=el.dataset.draft;if(field==='question'||field==='questionTopic'||field==='note')ui.writeDraft(context,field,el.value);if(field==='correlation')ui.writeDraft(context,field,readCorrelationForm());}storageNotice();}
function readCorrelationForm(){return {sources:[$('#source-a')?.value,$('#source-b')?.value].map(value=>publicSources().find(s=>sourceValue(s)===value)).map(s=>s?{kind:s.kind,id:s.id}:null),relation:$('#relation')?.value||'related',text:$('#hypothesis')?.value||''};}
async function command(path,body,entry=false){if(busy||pending)return false;saveDrafts();pending={path,body,entry,context:uiContext(state),questionTopicChoice:ui.read(uiContext(state)).questionTopic};storage.set('shift-pending',pending);if(body.type==='ask')clearQuestionConsent();return await runPending();}
async function runPending(){
 if(busy||!pending)return false;const focusBeforeBusy={composer:!!document.activeElement?.closest?.('#question-form'),version:focusVersion};busy=true;setBusy();const work=pending;
 try{
  const data=await fetchJson(work.path,{body:work.body});
  if(work.entry){session={code:data.code,playerId:data.playerId};storage.set('shift-session',session);}
  applyState(work.entry?data.state:data,{render:false});
  if(work.context){const type=work.body.type;const field=type==='ask'?'question':type==='note'?'note':type==='correlate'?'correlation':null;const sent=type==='ask'?work.body.question:type==='note'?work.body.text:{sources:work.body.sources,relation:work.body.relation,text:work.body.text};if(type==='ask'){clearQuestionConsent();const draft=ui.read(work.context);if(draft.question===sent&&draft.questionTopic===(work.questionTopicChoice??'')){ui.clearMatchingDraft(work.context,'question',sent);ui.clearMatchingDraft(work.context,'questionTopic',work.questionTopicChoice??'');}}else if(field)ui.clearMatchingDraft(work.context,field,sent);}
  pending=null;storage.remove('shift-pending');$('#notice').textContent='';const answerFocus=completedInterviewFocus(work,focusBeforeBusy);render();if(answerFocus)document.getElementById('answer-'+answerFocus)?.focus();return true;
 }catch(error){if(error.status&&error.status<500&&error.status!==429){pending=null;storage.remove('shift-pending');notice(error.message,true);}else notice(error.status===429?error.message:'Connection lost. Your action may have arrived. Retry safely without sending it twice.',true);return false;}
 finally{busy=false;setBusy();}
}
function completedInterviewFocus(work,focusBeforeBusy){
 const active=document.activeElement,composerOwnsFocus=!!active?.closest?.('#question-form');
 // Disabling Send can blur it to body. Do not mistake a later focus move for that blur.
 const disabledComposerBlur=focusBeforeBusy?.composer&&active===document.body&&focusVersion===focusBeforeBusy.version;
 if(work.body.type!=='ask'||stage!=='interrogate'||historyRound!==null||!sameContext(work.context,uiContext(state))||(!composerOwnsFocus&&!disabledComposerBlur))return null;
 const interview=currentInterview(),answer=interview?.messages.at(-1);
 return interview?.suspectId===work.context.suspect&&interview.messages.length>=4&&answer?.question===work.body.question.trim()?answer.id:null;
}
function setBusy(){document.body.classList.toggle('busy',busy);document.querySelectorAll('[data-submit]').forEach(b=>b.disabled=busy||!!pending||b.dataset.locked==='true');}
function act(type,data={}){if(pending){notice('Resolve the pending action before sending another.',true);return Promise.resolve(false);}return command(`/api/rooms/${session.code}/actions`,{id:newRequestId(),type,...data});}
function sameContext(a,b){return a&&b&&a.room===b.room&&a.player===b.player&&a.round===b.round&&a.phase===b.phase;}
function applyState(next,{render:shouldRender=true}={}){
 if(!next)return false;
 if(session&&(next.code!==session.code||next.me?.id!==session.playerId))return false;
 if(state&&next.code===state.code&&next.version<lastVersion)return false;
 saveDrafts();const previous=uiContext(state),context=uiContext(next),changed=previous&&!sameContext(previous,context);
 state=next;lastVersion=next.version;
 if(changed){closeConfirmation(false);stage='analyse';ui.setStage(context,stage);dossierId=null;selectedVote='';historyRound=null;search='';filter='all';sourceSearch='';history.replaceState(null,'','#analyse');announce(next.phase==='investigation'?`Round ${next.round} has started. Analyse the latest findings.`:phaseLabels[next.phase]);}
 else if(!previous){stage=ui.read(context).stage;ui.setStage(context,stage);history.replaceState(null,'',`#${stage}`);}
 if(shouldRender)render();return true;
}
function navigate(next,{history:mode='push',focus=true}={}){
 if(!STAGES.includes(next))return;saveDrafts();if(next==='interrogate'&&stage!==next)historyRound=null;stage=next;ui.setStage(uiContext(state),stage);
 if(mode==='push')history.pushState(null,'',`#${stage}`);else if(mode==='replace')history.replaceState(null,'',`#${stage}`);
 render();if(focus)$('#stage-heading')?.focus({preventScroll:false});
}
function stampFocusKeys(){for(const el of document.querySelectorAll('button,input,select,textarea,summary,a')){if(el.id){el.dataset.focusKey='id:'+el.id;continue;}const scope=el.closest('form')?.id||el.closest('details')?.id||(el.closest('#header')?'header':'main');if(el.dataset.action)el.dataset.focusKey=`action:${scope}:${el.dataset.action}:${el.dataset.id??''}`;else if(el.dataset.stage)el.dataset.focusKey=`stage:${scope}:${el.dataset.stage}`;else if(el.dataset.entry)el.dataset.focusKey='entry:'+el.dataset.entry;else if(el.tagName==='SUMMARY')el.dataset.focusKey='summary:'+scope;else if(el.tagName==='INPUT'&&el.type==='radio')el.dataset.focusKey=`radio:${scope}:${el.name}:${el.value}`;else if(el.tagName==='BUTTON'&&el.closest('form'))el.dataset.focusKey='submit:'+scope;else if(el.tagName==='A')el.dataset.focusKey=`link:${scope}:${el.getAttribute('href')}`;}}
function focusLocator(el){return el?{id:el.id||null,key:el.dataset?.focusKey||null}:null;}
function focusElement(locator){if(!locator)return null;return (locator.id?document.getElementById(locator.id):null)||(locator.key?[...document.querySelectorAll('[data-focus-key]')].find(el=>el.dataset.focusKey===locator.key):null);}
function capture(){const active=document.activeElement;return {focus:focusLocator(active),start:active?.selectionStart,end:active?.selectionEnd,scroll:$('#transcript')?.scrollTop,details:[...document.querySelectorAll('details[id]')].map(el=>({id:el.id,open:el.open}))};}
function restore(old){for(const detail of old.details??[]){const el=document.getElementById(detail.id);if(el)el.open=detail.open;}const el=focusElement(old.focus);if(el){el.focus({preventScroll:true});if(el.setSelectionRange&&typeof old.start==='number')try{el.setSelectionRange(old.start,old.end);}catch{}}if(typeof old.scroll==='number'&&$('#transcript'))$('#transcript').scrollTop=old.scroll;}
function render(){syncQuestionConsent();const old=capture();const entryValues={};if(!state)for(const el of document.querySelectorAll('input,select'))if(el.id)entryValues[el.id]=el.value;frame();$('#main').innerHTML=!state?landing():state.phase==='lobby'?lobby():state.phase==='reveal'?reveal():game();if(!state)for(const [id,value]of Object.entries(entryValues)){const el=document.getElementById(id);if(el)el.value=value;}stampFocusKeys();restore(old);storageNotice();setBusy();}
function frame(){const active=!!state;$('#header').innerHTML=`<a class="wordmark" href="/" aria-label="SHIFT The Timeline"><span class="brand-name">SHIFT</span><small>THE TIMELINE</small></a><div class="header-meta">${active?`<span class="phase-label">${esc(phaseLabels[state.phase])}</span><button id="room-code" class="room-code" data-action="copy" aria-label="Copy room code ${esc(state.code)}">${esc(state.code)} <span aria-hidden="true">⧉</span></button>`:'<span>Temporal Investigation Bureau</span>'}</div>`;}
function filmCard(id,compact=false){const titles={train:'The night train','pocket-watch':'The pocket watch',corridor:'The empty corridor'};return `<figure class="scene-card ${compact?'scene-card-compact':''}"><img src="/assets/films/${id}.webp" alt="" width="960" height="540" loading="lazy" decoding="async"><figcaption><div><small>ATMOSPHERE ONLY · 10 SECONDS</small><b>${titles[id]}</b></div><button id="case-film-open" type="button" class="secondary" data-film-open="${id}" aria-label="Play ${titles[id]}"><span aria-hidden="true">▷</span> Play scene</button></figcaption><p class="muted">Atmosphere only, not case evidence. Three optional films.</p></figure>`;}
function landing(){return `<section class="landing"><div class="hero"><p class="eyebrow">THE FUTURE IS STILL AN OPEN CASE</p><h1>A crime foretold.<br>A future <em>unwritten.</em></h1><p class="lead">You know who will die, where and how. Find who is behind it before the timeline becomes history.</p><div class="hero-facts"><span><b>3–4</b> players</span><span><b>15</b> suspects</span><span><b>3</b> rounds</span></div>${filmCard('train')}<ol class="how">${STAGES.map((s,i)=>`<li><img src="/assets/steps/${s}.webp" alt="" width="64" height="64"><div><b>${i+1}. ${stageLabels[s]}</b><p>${['Review the known facts and choose whom to hear.','Question one suspect in a private conversation.','Connect your findings and finish the round.'][i]}</p></div></li>`).join('')}</ol></div><aside class="entry-panel"><div class="entry-switch" aria-label="Room options"><button data-entry="create" aria-pressed="${entryMode==='create'}">Create a room</button><button data-entry="join" aria-pressed="${entryMode==='join'}">Join with a code</button></div><h2>${entryMode==='create'?'Open an investigation':'Join your team'}</h2>${entryMode==='create'?`<form id="create-form"><label for="create-name">Your codename</label><input id="create-name" name="name" required maxlength="24" autocomplete="nickname" placeholder="Choose an agent name"><label for="case-choice">Case</label><select id="case-choice" name="caseId">${cases.map(c=>`<option value="${esc(c.id)}" ${c.available?'':'disabled'}>${esc(c.title)}${c.available?'':' · in development'}</option>`).join('')}</select><button class="primary full" data-submit>Create room <span aria-hidden="true">→</span></button></form>`:`<form id="join-form"><label for="join-name">Your codename</label><input id="join-name" name="name" maxlength="24" required autocomplete="nickname" placeholder="Choose an agent name"><label for="join-code">Eight-character room code</label><input id="join-code" name="code" required minlength="8" maxlength="8" pattern="[A-HJ-NP-Za-hj-np-z2-9]{8}" placeholder="ABCD2345" autocapitalize="characters" autocomplete="off" spellcheck="false"><button class="primary full" data-submit>Join room <span aria-hidden="true">→</span></button></form>`}<p class="prototype-note"><strong>Canonical dialogue prototype.</strong> ${optionalAi?'Optional OpenAI voice is available only with per-question consent; it is not evidence.':'Generative AI is not connected.'} Rooms expire after 6 hours without actions, or 24 hours from creation. Use codenames, not sensitive personal information.</p></aside></section>`;}
function recoveryControls(){
 if(!state||state.phase==='reveal')return '';
 const recovery={canFinalize:state.canFinalizeAccusations,missingCount:state.players.filter(p=>!p.voteSubmitted).length};
 return `<section class="recovery-controls"><h2>Connection recovery</h2><p class="muted">Keep this page connected while playing. After two minutes without contact, another agent can take over an absent host. No one can see or change another player's accusation.</p>${state.hostRecoverable&&!state.me.host?'<button class="secondary" data-action="claimHost" data-submit>Take over as host</button>':''}${state.me.host&&state.phase==='accusation'&&recovery?.missingCount?`<p>${recovery.missingCount} accusation(s) still missing. ${recovery.canFinalize?'All missing agents have been out of contact for at least two minutes.':`Wait for disconnected agents to return. Recovery is available only after every missing agent has been out of contact for two minutes.`}</p>${recovery.canFinalize?'<button class="secondary danger" data-action="finalizeAccusations" data-submit>Finish with missing accusations</button>':''}`:''}</section>`;
}
function lobby(){return `<section class="lobby"><p class="eyebrow">YOUR TEAM. ONE TIMELINE.</p><h1>Assemble the unit.</h1><p class="lead">Share this address and room code with your team. Each player needs their own browser session.</p><div class="invite"><span class="selectable-code">${esc(state.code)}</span><button class="secondary" data-action="copy">Copy room code</button></div>${filmCard('corridor')}<ul class="roster">${state.players.map(p=>`<li><span class="agent-mark" aria-hidden="true">${esc(p.name.slice(0,1))}</span><span><b>${esc(p.name)}${p.id===state.me.id?' (you)':''}</b><small>${p.host?'Host':'Temporal agent'}</small></span><span class="pill">Joined</span></li>`).join('')}</ul><div class="lobby-bottom"><div><h2>${esc(state.case.title)}</h2><p>One suspect per round. Up to four questions per interview. Compare evidence before deciding.</p><p class="muted">The 24-hour countdown belongs to the story, not a real-time timer.</p></div>${state.me.host?`<button class="primary" data-action="start" data-submit ${state.players.length<3?'disabled data-locked="true"':''}>${state.players.length<3?'Waiting for 3 players':'Begin investigation →'}</button>`:'<p>The host will start the investigation.</p>'}</div><p class="muted">Return using this same browser to reconnect. This room lasts up to 6 hours without game actions or 24 hours in total.</p>${recoveryControls()}</section>`;}
function team(){return `<details id="team-panel" class="team-details"><summary>${state.players.filter(p=>state.phase==='accusation'?p.voteSubmitted:p.ready).length} of ${state.players.length} ${state.phase==='accusation'?'accusations submitted':'rounds finished'} <span>Team status</span></summary><ul>${state.players.map(p=>`<li><b>${esc(p.name)}${p.id===state.me.id?' (you)':''}</b><span>${state.phase==='accusation'?(p.voteSubmitted?'Submitted privately':'Deciding'):p.ready?'Round finished':p.selectedSuspectId?`Interviewing ${esc(person(p.selectedSuspectId)?.name)}`:'Choosing a suspect'}</span></li>`).join('')}</ul></details>`;}
function stepper(){return `<nav class="stepper" aria-label="Investigation stages"><ol>${STAGES.map((s,i)=>`<li><button id="stage-${s}" data-stage="${s}" ${s===stage?'aria-current="step"':''}><img src="/assets/steps/${s}.webp" alt="" width="36" height="36"><span><small>${i+1}</small> ${stageLabels[s]}</span></button></li>`).join('')}</ol></nav>`;}
function caseFacts(expanded=false){return `<details id="case-facts-panel" class="case-facts" ${expanded?'open':''}><summary>Known facts <span>The forecast</span></summary><dl><dt>Victim</dt><dd>${esc(state.case.victim)}</dd><dt>Place</dt><dd>${esc(state.case.place)}</dd><dt>Method</dt><dd>${esc(state.case.method)}</dd></dl><p>${esc(state.case.prediction)}</p></details>`;}
function game(){const accusation=state.phase==='accusation';return `<section class="game-shell"><div class="round-bar"><span class="case-name">${esc(state.case.title)}</span><b>${accusation?'Accusation':`Round ${state.round} of 3`}</b><span class="story-clock">${state.remainingHours}h <small>in the story</small></span></div>${accusation?`<nav class="review-nav" aria-label="Accusation review"><button data-stage="analyse" ${stage==='analyse'?'aria-current="page"':''}>Your accusation</button><button data-stage="interrogate" ${stage==='interrogate'?'aria-current="page"':''}>Review your interviews</button><button data-stage="deduce" ${stage==='deduce'?'aria-current="page"':''}>Review team board</button></nav>`:stepper()}${team()}<div class="workspace"><div class="stage-content">${accusation?(stage==='deduce'?deduce():stage==='interrogate'?interrogate():voting()):stage==='analyse'?analyse():stage==='interrogate'?interrogate():deduce()}</div><aside class="context-panel">${stage!=='analyse'||accusation?caseFacts():''}${filmCard(stage==='interrogate'?'corridor':'pocket-watch',true)}<details id="rules-panel" class="rules"><summary>Investigation rules</summary><p>Three rounds. One suspect each round. Up to four questions. Your interviews are private until you explicitly share an answer.</p><p>Shared correlations are player hypotheses, not verified evidence.</p><p>Canonical dialogue. ${optionalAi?'Optional OpenAI voice is available only with per-question consent; it is not evidence.':'Generative AI is not connected.'}</p></details>${state.me.host&&!accusation?'<details id="host-panel" class="host-controls"><summary>Host controls</summary><p>Only use this after agreeing with your team. Unused questions will be lost.</p><button class="text-button danger" data-action="advance" data-submit>End round for everyone</button></details>':''}${recoveryControls()}${recoverDrafts()}</aside></div></section>`;}
function analyse(){const current=currentInterview();const selected=person(dossierId);const list=state.suspects.filter(s=>(s.name+' '+s.role).toLocaleLowerCase('en-GB').includes(search.toLocaleLowerCase('en-GB'))&&(filter==='unheard'?!state.me.interviews.some(i=>i.suspectId===s.id):filter==='interviewing'?state.players.some(p=>p.selectedSuspectId===s.id):true));return `<header class="section-intro"><p class="eyebrow">01 / BUILD THE PICTURE</p><h1 id="stage-heading" tabindex="-1">What do we know?</h1><p>Review the facts. Find the person worth hearing next.</p></header>${caseFacts()}${state.board.some(n=>n.type==='clue')?`<details id="shared-panel" class="shared-findings"><summary>${state.board.filter(n=>n.type==='clue').length} shared findings</summary>${boardRecords(state.board.filter(n=>n.type==='clue'))}</details>`:''}<div class="section-heading"><h2>Suspect dossiers</h2><span>${state.suspects.length} people</span></div>${current?`<div class="callout"><b>${esc(person(current.suspectId)?.name)} is your suspect this round.</b><p>${current.closed?'Your interview is closed. You can still review your findings.':'You cannot change this selection until the next round.'}</p><button class="secondary" data-stage="interrogate">${current.closed?'Review interview':'Resume interview'} →</button></div>`:''}<div class="search-tools"><div><label for="suspect-search">Search name or role</label><input id="suspect-search" type="search" value="${esc(search)}" placeholder="Find a suspect…"></div><div><label for="suspect-filter">Show</label><select id="suspect-filter"><option value="all" ${filter==='all'?'selected':''}>All suspects</option><option value="unheard" ${filter==='unheard'?'selected':''}>Not yet heard by you</option><option value="interviewing" ${filter==='interviewing'?'selected':''}>Being interviewed</option></select></div></div><div class="suspect-grid">${list.map(s=>`<button class="suspect-card ${dossierId===s.id?'selected':''}" data-action="dossier" data-id="${esc(s.id)}" aria-pressed="${dossierId===s.id}" aria-label="View ${esc(s.name)}, ${esc(s.role)}">${avatar(s)}<span class="suspect-info"><small>${esc(s.role)}</small><b>${esc(s.name)}</b><span>${state.players.some(p=>p.selectedSuspectId===s.id)?'Being interviewed':state.me.interviews.some(i=>i.suspectId===s.id)?'Previously heard by you':'Not yet heard by you'}</span>${dossierId===s.id?'<strong>Selected dossier</strong>':''}</span></button>`).join('')||'<p class="empty-state">No suspects match your search.</p>'}</div>${selected?`<article class="dossier-detail" id="dossier-detail" tabindex="-1">${avatar(selected,true)}<div><p class="eyebrow">PUBLIC DOSSIER</p><h2>${esc(selected.name)}</h2><p class="role">${esc(selected.role)}</p><p>${esc(selected.profile)}</p>${state.players.filter(p=>p.id!==state.me.id&&p.selectedSuspectId===selected.id).map(p=>`<p class="muted">${esc(p.name)} is already speaking to this person. You may choose the same suspect, but your team will cover fewer people.</p>`).join('')}${!current?`<button class="primary" data-action="select" data-id="${esc(selected.id)}" data-submit>Interrogate ${esc(selected.name.split(' ')[0])} →</button><p class="muted">This uses your one suspect choice for this round.</p>`:'<p class="muted">Dossiers remain available to read after choosing.</p>'}</div></article>`:''}`;}
function renderNarration(message){
 const narration=message.narration;
 if(narration?.status==='pending')return '<aside class="generated-voice" role="status" aria-live="polite"><small>OPTIONAL AI VOICE · PREPARING</small><p class="muted">Your case evidence is ready. Optional voice is being prepared; you can keep investigating.</p></aside>';
 if(narration?.status==='fallback')return '<aside class="generated-voice" role="status" aria-live="polite"><small>OPTIONAL AI VOICE · UNAVAILABLE</small><p class="muted">Use the case evidence above. No extra question is needed, and this voice request will not be retried automatically.</p></aside>';
 return narration?.status==='complete'?`<aside class="generated-voice" role="note" aria-label="Unverified AI voice"><small>AI VOICE · NOT EVIDENCE</small><p class="muted">AI voice may invent or contradict facts. Use case evidence for deductions.</p><p>${esc(narration.text)}</p></aside>`:'';
}
function messageById(id){for(const i of state?.me.interviews??[]){const message=i.messages.find(m=>m.id===id);if(message)return {interview:i,message};}return null;}
function interviewHistory(){const older=state.me.interviews.filter(i=>i.round!==state.round);return older.length?`<label for="interview-round">Interview history</label><select id="interview-round"><option value="current" ${historyRound===null?'selected':''}>Round ${state.round} · Current interview${currentInterview()?'':' · Not started'}</option>${[...older].reverse().map(i=>`<option value="${i.round}" ${historyRound===i.round?'selected':''}>Round ${i.round} · ${esc(person(i.suspectId)?.name)} · Closed</option>`).join('')}</select>`:'';}
function topicCoverage(interview){const active=state.phase==='investigation'&&interview.round===state.round&&!interview.closed&&interview.messages.length<4;return `<div class="topics" aria-label="Interview topics">${Object.entries(topicLabels).map(([key,label])=>{const heard=interview.messages.some(m=>m.topic===key);return `<button class="topic" data-action="${heard?'review-topic':'topic'}" data-id="${key}" ${!heard&&!active?'disabled':''}>${esc(label)}${heard?' · Review answer':''}</button>`;}).join('')}</div>`;}
function reviewTopic(topic){const interview=historyRound===null?currentInterview():state.me.interviews.find(i=>i.round===historyRound);const message=interview?.messages.find(m=>m.topic===topic);if(!message)return;const target=document.getElementById('answer-'+message.id);target?.focus({preventScroll:true});target?.scrollIntoView?.({block:'nearest',behavior:'smooth'});}
function topicHint(question,interview=currentInterview(),choice=ui.read(uiContext(state)).questionTopic){if(!question.trim())return 'Choose a topic or write a question. Each topic has one canonical answer.';const topic=Object.hasOwn(topicLabels,choice)?choice:questionTopic(question);return `${{alibi:'Alibi',motive:'Motive',clue:'Observations',relationship:'Relationship'}[topic]} · ${interview?.messages.some(m=>m.topic===topic)?'Already covered. Review the answer above; another question will not be used.':'One question will be used. Canonical matching is not AI understanding.'}`;}
function interrogate(){const interviews=state.me.interviews,accusation=state.phase==='accusation';if(accusation&&historyRound===null&&!currentInterview())historyRound=interviews.at(-1)?.round??null;const chosen=historyRound===null?currentInterview():interviews.find(i=>i.round===historyRound);if(!chosen)return `<header class="section-intro"><p class="eyebrow">02 / PRIVATE CONVERSATION</p><h1 id="stage-heading" tabindex="-1">${accusation?'No interviews to review.':'Who will you question?'}</h1><p>${accusation?'You did not record an interview before accusations began. You can still review the team board.':'Select a dossier in Analyse to begin your private interview.'}</p>${interviewHistory()}<button class="primary" data-stage="analyse">${accusation?'Return to your accusation →':'Choose a suspect →'}</button></header>`;const s=person(chosen.suspectId),active=state.phase==='investigation'&&chosen.round===state.round&&!chosen.closed,draft=ui.read(uiContext(state));return `<header class="section-intro"><p class="eyebrow">02 / PRIVATE CONVERSATION</p><h1 id="stage-heading" tabindex="-1">Hear their account.</h1></header>${interviewHistory()}<article class="interview"><header class="interview-head">${avatar(s)}<div><span class="pill">Round ${chosen.round} · Private${chosen.round!==state.round?' · History':''}</span><h2>${esc(s.name)}</h2><p>${esc(s.role)}</p></div><strong class="question-count">${chosen.messages.length}<span> / 4</span><small>questions used</small></strong></header>${topicCoverage(chosen)}<div class="transcript" id="transcript"><div class="bubble answer"><b>${esc(s.name)}</b><p>${esc(chosen.opening)}</p></div>${chosen.messages.map(m=>`<div class="bubble question"><b>You</b><p>${esc(m.question)}</p></div><div class="bubble answer" id="answer-${esc(m.id)}" tabindex="-1"><b>${esc(s.name)}</b><span class="record-label">Case evidence</span><p>${esc(m.answer)}</p>${renderNarration(m)}${['investigation','accusation'].includes(state.phase)?`<button class="share-button" data-action="share" data-id="${esc(m.id)}" data-submit ${state.board.some(n=>n.messageId===m.id)?'disabled data-locked="true"':''}>${state.board.some(n=>n.messageId===m.id)?'Shared with your team':'Share evidence ↗'}</button>`:''}</div>`).join('')}</div>${active&&chosen.messages.length<4?`<div class="interview-controls"><p class="muted">Choose a prompt or write a question. ${optionalAi?'Canonical topics determine the evidence. AI voice is optional and is not evidence. Each response uses this question and its case evidence, not earlier conversation.':'Canonical topics determine the answer; generative AI is not active.'}</p><form id="question-form">${optionalAi?'<label><input id="question-ai-consent" type="checkbox" name="aiConsent" value="yes" '+(questionConsentKey!==null?'checked':'')+'> Add optional AI voice for this question. It can invent or contradict facts and is not evidence. Send this question, the suspect’s fictional profile and this canonical answer to OpenAI. Do not enter personal information. Leave unchecked to keep this question out of OpenAI. It is still stored by the game service.</label>':''}<label for="question-topic">Answer topic</label><select id="question-topic" name="topic" data-draft="questionTopic" aria-describedby="topic-hint"><option value="">Automatic</option>${Object.entries({alibi:'Alibi',clue:'Observations',motive:'Motive',relationship:'Relationship'}).map(([key,label])=>`<option value="${key}" ${draft.questionTopic===key?'selected':''}>${label}</option>`).join('')}</select><p class="muted">Automatic matches keywords. Choose a topic to keep your own wording and direct the question.</p><label for="question">Your question</label><textarea id="question" name="question" data-draft="question" required maxlength="300" rows="3" aria-describedby="question-help topic-hint">${esc(draft.question)}</textarea><p id="topic-hint" role="status" class="muted">${esc(topicHint(draft.question,chosen))}</p><div class="composer-meta"><small id="question-help">Draft in this browser · <span id="question-count">${draft.question.length}</span>/300</small><button class="primary" data-submit>Send question →</button></div></form></div>`:`<p class="callout">${accusation?'Questioning has ended. You can review and share your existing evidence.':chosen.closed?'This interview is closed. Your account remains available to review.':'All four questions have been used. Review your findings before finishing the round.'}</p>`}</article><div class="stage-actions"><button class="text-button" data-stage="analyse">${accusation?'Return to your accusation →':'← Analyse'}</button><button class="secondary" data-stage="deduce">${accusation?'Review team board →':'Go to Deduce →'}</button></div>${accusation?'':'<p class="muted">Moving to Deduce does not end your interview or use any remaining questions.</p>'}`;}
function sourceValue(s){return `${s.kind}:${s.id}`;}
function publicSources(){if(!state)return [];return [...['victim','place','method','prediction'].map(id=>({kind:'case',id,title:{victim:'Victim',place:'Place',method:'Method',prediction:'Forecast'}[id],text:state.case[id]})),...state.suspects.map(s=>({kind:'suspect',id:s.id,title:s.name,text:[s.role,s.profile].filter(Boolean).join('\n\n')})),...state.board.filter(n=>n.type==='clue').map(n=>({kind:'clue',id:n.id,title:`Evidence: ${n.source}`,text:n.text}))];}
function sourceFor(ref){return publicSources().find(s=>s.kind===ref?.kind&&s.id===ref?.id);}
function sourcePreview(ref,label){const source=ref?sourceFor(ref):null;return `<h3>${esc(label)} · Source preview</h3>${source?`<p class="record-label">${source.kind==='clue'?'Shared case evidence':source.kind==='suspect'?'Public dossier':'Public case fact'}</p><strong>${esc(source.title)}</strong><p>${esc(source.text)}</p>`:`<p class="muted">${ref?'This source is unavailable. Choose another public source.':'Choose a public source above to read its full text.'}</p>`}`;}
function updateSourcePreviews(){const sources=ui.read(uiContext(state)).correlation.sources;for(const [index,id,label]of [[0,'source-preview-a','Source A'],[1,'source-preview-b','Source B']]){const panel=document.getElementById(id);if(panel)panel.innerHTML=sourcePreview(sources[index],label);}}
function sourceOptions(selected){return '<option value="">Choose a public source…</option>'+publicSources().filter(s=>sourceValue(s)===selected||`${s.title} ${s.text}`.toLocaleLowerCase('en-GB').includes(sourceSearch.toLocaleLowerCase('en-GB'))).map(s=>`<option value="${esc(sourceValue(s))}" ${sourceValue(s)===selected?'selected':''}>${esc(s.title)} · ${esc(s.text?.slice(0,90))}</option>`).join('');}
function boardRecords(records){return `<div class="board-records">${[...records].reverse().map(n=>`<article class="board-record ${esc(n.type)}"><span class="record-label">${n.type==='clue'?'Shared evidence':n.type==='correlation'?'Team hypothesis':'Team note'}</span>${n.type==='clue'?`<h3>${esc(n.source)}</h3>`:n.type==='correlation'?`<div class="source-link">${n.sources.map(ref=>`<details id="source-${esc(n.id)}-${esc(ref.kind)}-${esc(ref.id)}"><summary>${esc(sourceFor(ref)?.title||'Public source')}</summary><p>${esc(sourceFor(ref)?.text||'Source unavailable')}</p></details>`).join(`<b>${esc(relationLabels[n.relation])}</b>`)}</div>`:''}<p>${esc(n.text)}</p><small>${esc(n.by)} · Round ${n.round}${n.type==='correlation'?' · Unverified':''}</small></article>`).join('')||'<div class="empty-state"><h3>The pieces are still separate.</h3><p>Share an interview answer or add your first hypothesis.</p></div>'}</div>`;}
function privateFindings(){const privateAnswers=state.me.interviews.flatMap(i=>i.messages.filter(m=>!state.board.some(n=>n.messageId===m.id)).map(m=>({m,i})));return privateAnswers.length?`<details id="private-panel" class="private-findings"><summary>Only you know <span>${privateAnswers.length} unshared answers</span></summary><p>These answers are private. Share each one explicitly before linking it on the team board.</p>${privateAnswers.map(({m,i})=>`<article><b>${esc(person(i.suspectId)?.name)} · Round ${i.round}</b><p>${esc(m.answer)}</p><button class="secondary" data-action="share" data-id="${esc(m.id)}" data-submit>Preview evidence to share</button></article>`).join('')}</details>`:'';}
function renderRoundReview(){if(state.phase!=='investigation')return '';const i=currentInterview();return `<section class="round-review"><h2>Review your round</h2>${i?`<dl><dt>Interviewed</dt><dd>${esc(person(i.suspectId)?.name)}</dd><dt>Questions used</dt><dd>${i.messages.length} of 4</dd><dt>Answers shared</dt><dd>${i.messages.filter(m=>state.board.some(n=>n.messageId===m.id)).length}</dd><dt>Answers still private</dt><dd>${i.messages.filter(m=>!state.board.some(n=>n.type==='clue'&&n.messageId===m.id)).length}</dd><dt>Correlations</dt><dd>${state.board.filter(n=>n.type==='correlation'&&n.round===state.round&&n.by===state.me.name).length}</dd></dl>${i.closed?`<p class="callout">Your round is finished. Waiting for ${state.players.filter(p=>!p.ready).length} agent(s). You can still review and contribute to the board.</p>`:'<button class="primary full" data-action="end" data-submit>Finish my round →</button>'}`:'<p>Choose one suspect before you can finish this round.</p><button class="secondary" data-stage="analyse">Choose a suspect →</button>'}<p class="muted">Sharing answers and creating correlations are optional. You can finish without either. Nothing is shared automatically when you finish.</p></section>`;}
function deduce(){const d=ui.read(uiContext(state)),full=state.board.length>=60;return `<header class="section-intro"><p class="eyebrow">${state.phase==='accusation'?'REVIEW THE EVIDENCE':'03 / CONNECT THE FINDINGS'}</p><h1 id="stage-heading" tabindex="-1">Build your theory.</h1><p>Link what the team knows. A connection is a hypothesis, not a verdict.</p></header>${renderRoundReview()}<div class="board-capacity">${state.board.length} / 60 board records <span>${full?'Board full. You can still review and finish.':`${60-state.board.length} spaces remaining`}</span></div>${privateFindings()}<form id="correlation-form" class="correlation-form"><h2>Create a correlation</h2><p class="muted">Choose two public sources. Private interviews never enter a correlation automatically.</p><label for="source-search">Find sources</label><input id="source-search" type="search" value="${esc(sourceSearch)}" placeholder="Search facts, people or shared evidence"><div class="source-pair"><div><label for="source-a">Source A</label><select id="source-a" required>${sourceOptions(d.correlation.sources[0]?sourceValue(d.correlation.sources[0]):'')}</select></div><div><label for="source-b">Source B</label><select id="source-b" required>${sourceOptions(d.correlation.sources[1]?sourceValue(d.correlation.sources[1]):'')}</select></div></div><div class="source-pair"><section id="source-preview-a" class="source-preview" aria-live="polite" aria-atomic="true">${sourcePreview(d.correlation.sources[0],'Source A')}</section><section id="source-preview-b" class="source-preview" aria-live="polite" aria-atomic="true">${sourcePreview(d.correlation.sources[1],'Source B')}</section></div><p class="muted">Compare the exact wording before describing a connection. A hypothesis does not make either source proof of a verdict.</p><label for="relation">How might they connect?</label><select id="relation">${Object.entries(relationLabels).map(([key,label])=>`<option value="${key}" ${key===d.correlation.relation?'selected':''}>${label}</option>`).join('')}</select><label for="hypothesis">Your hypothesis</label><textarea id="hypothesis" data-draft="correlation" required maxlength="300" rows="3">${esc(d.correlation.text)}</textarea><div class="composer-meta"><small>Draft in this browser · <span id="hypothesis-count">${d.correlation.text.length}</span>/300</small><button class="primary" data-submit ${full?'disabled data-locked="true"':''}>Preview correlation →</button></div><p class="muted">Shared correlations are visible to your team and cannot be edited or deleted in this prototype.</p></form><details id="team-note-panel" class="team-note"><summary>Add a team note</summary><form id="note-form"><label for="note">A note, not evidence</label><textarea id="note" name="text" data-draft="note" required maxlength="500" rows="3">${esc(d.note)}</textarea><small>Draft in this browser · 500 characters maximum</small><button class="secondary" data-submit ${full?'disabled data-locked="true"':''}>Share team note</button></form></details><div class="section-heading"><h2>Team board</h2><span>Sources and hypotheses</span></div>${boardRecords(state.board)}${state.phase==='accusation'?'<button class="primary full" data-stage="analyse">Return to your accusation →</button>':''}`;}
function recoverDrafts(){const records=ui.recoverable(uiContext(state));return records.length?`<details id="recovery-panel" class="recovery"><summary>Recover earlier local drafts <span>${records.length}</span></summary><p>These drafts were not sent. They remain in their original round and will not be reused automatically.</p>${records.map(r=>`<article><b>Round ${r.round} · ${r.field==='correlation'?'Hypothesis':r.field==='question'?'Question':'Note'}${r.suspect?' · '+esc(person(r.suspect)?.name||'previous suspect'):''}</b><textarea readonly aria-label="Unsent draft from round ${r.round}">${esc(r.field==='correlation'?r.value.text:r.value)}</textarea><small>Select and copy text if you wish to use it again.</small></article>`).join('')}</details>`:'';}
function voting(){if(state.me.vote)return `<header class="section-intro"><p class="eyebrow">PRIVATE DECISION RECORDED</p><h1 id="stage-heading" tabindex="-1">Your accusation is sealed.</h1><p>You chose <strong>${esc(person(state.me.vote)?.name)}</strong>. It cannot be changed.</p><p>Waiting for ${state.players.filter(p=>!p.voteSubmitted).length} agent(s). A disconnected player can return using the same browser.</p><button class="secondary" data-stage="deduce">Review the team board →</button></header>`;return `<header class="section-intro"><p class="eyebrow">INDIVIDUAL DECISION. SHARED CONSEQUENCES.</p><h1 id="stage-heading" tabindex="-1">Who will you accuse?</h1><p>Identifying the culprit prevents the crime, but each innocent person accused is also arrested. Your choice is private and final.</p></header><form id="vote-form"><fieldset><legend>Choose one suspect</legend><div class="vote-grid">${state.suspects.map(s=>`<label class="vote-option">${avatar(s)}<span><b>${esc(s.name)}</b><small>${esc(s.role)}</small></span><input type="radio" name="suspectId" value="${esc(s.id)}" required ${selectedVote===s.id?'checked':''}></label>`).join('')}</div></fieldset><button class="primary full" data-submit>Review my accusation →</button></form>`;}
function reveal(){const r=state.result,s=person(r.culpritId),titles={complete:'The future has changed.',partial:'A life saved. An incomplete verdict.',defeat:'The forecast came true.'},descriptions={complete:'Everyone identified the culprit. The crime was prevented without arresting anyone innocent.',partial:r.innocentArrests?'The culprit was identified and the crime prevented, but the team also accused innocent people.':'The culprit was identified and the crime prevented, but not every agent submitted a correct accusation.',defeat:'No one identified the culprit. They remained free to carry out the crime.'};return `<section class="reveal"><p class="eyebrow">CASE CLOSED / ${r.outcome==='complete'?'COMPLETE VICTORY':r.outcome==='partial'?'PARTIAL VICTORY':'DEFEAT'}</p><h1>${titles[r.outcome]}</h1><p class="lead">${descriptions[r.outcome]}</p><div class="result-stats"><span><b>${r.correct}/${r.total}</b> correct accusations</span><span><b>${r.innocentArrests}</b> innocent people arrested</span><span><b>${r.abstentions||0}</b> abstentions</span></div><div class="solution-grid"><article>${avatar(s,true)}<h2>${esc(s.name)}</h2><p>${esc(r.solution.motive)}</p><h3>The plan</h3><p>${esc(r.solution.plan)}</p></article><article><h2>How the evidence fits</h2><ol>${r.solution.evidence.map(e=>`<li>${esc(e)}</li>`).join('')}</ol><h3>The timeline</h3>${r.solution.timeline.map(t=>`<div class="timeline-event"><b>${esc(t.time)}</b><p>${esc(t.text)}</p></div>`).join('')}</article></div><ul class="verdicts">${r.votes.map(v=>`<li><b>${esc(state.players.find(p=>p.id===v.playerId)?.name)}</b><span>${v.suspectId?esc(person(v.suspectId)?.name):'No accusation submitted'}</span><strong>${v.correct?'Correct accusation':v.suspectId?'Innocent person accused':'Abstention'}</strong></li>`).join('')}</ul><p class="muted">This is a fixed case. Replaying reveals the same solution. Four other settings are still in development.</p><button class="primary" data-action="reset">Return to the beginning →</button></section>`;}
function closeConfirmation(returnFocus=true){confirmation=null;$('#confirm-dialog')?.close();if(returnFocus){const target=focusElement(confirmationTrigger);(target||$('#stage-heading'))?.focus({preventScroll:true});}confirmationTrigger=null;}
function openConfirmation(kind,payload){
 if(busy||pending)return;saveDrafts();let title='',body='',label='Confirm';const context=uiContext(state),i=currentInterview();
 if(kind==='select'){const s=person(payload.suspectId);if(!s||i)return;title=`Interrogate ${s.name}?`;body='<p>This is your one suspect choice for this round. Opening a dossier alone does not make this choice.</p>';label='Choose this suspect';}
 else if(kind==='share'){const found=messageById(payload.messageId);if(!found)return;if(state.board.length>=60){notice('The board is full. Existing findings remain available.',true);return;}title='Share this evidence?';body=`<p class="canonical-preview">${esc(found.message.answer)}</p><p>Only this canonical answer is shared with your team. Your question and any narration remain private.</p>`;label='Share evidence';}
 else if(kind==='correlate'){const {sources,relation,text}=payload;if(state.board.length>=60){notice('The board is full. Your draft has not been sent.',true);return;}if(!Array.isArray(sources)||sources.length!==2||sources.some(s=>!sourceFor(s))||sourceValue(sources[0])===sourceValue(sources[1])||!relationLabels[relation]||typeof text!=='string'||!text.trim()||text.length>300){notice('Choose two different public sources and write a hypothesis of 1–300 characters.',true);return;}title='Share your correlation?';body=`<p><b>Team hypothesis · Unverified</b></p><p>${esc(sourceFor(sources[0]).title)} <b>${esc(relationLabels[relation])}</b> ${esc(sourceFor(sources[1]).title)}</p><p class="canonical-preview">${esc(text)}</p><p>Everyone in your team can read this. It cannot be edited or deleted after sharing.</p>`;label='Share correlation';}
 else if(kind==='end'){if(!i||i.closed)return;const drafts=ui.read(context),hasDraft=drafts.question.trim()||drafts.note.trim()||drafts.correlation.text.trim();title='Finish your round?';body=`<p>You will not be able to ask more questions this round.${i.messages.length<4?` Your ${4-i.messages.length} unused question(s) will be lost.`:''}</p><p>When everyone finishes, ${state.round===3?'the accusation begins':'the next round starts'}.</p>${hasDraft?'<p>Your unsent drafts are local only and will not be shared. They remain available under earlier local drafts if the round changes.</p>':''}`;label='Finish my round';}
 else if(kind==='advance'){if(!state.me.host)return;title='End the round for everyone?';body='<p>All remaining questions will be lost. Unsent drafts stay local and will not be shared. Only continue after agreeing with your team.</p>';label='End round for everyone';}
 else if(kind==='claimHost'){if(!state.hostRecoverable||state.me.host)return;title='Take over as host?';body='<p>The host has not contacted the server for at least two minutes. You will control the round. They remain in the game and can reconnect; no interview or accusation is removed.</p>';label='Take over as host';}
 else if(kind==='finalizeAccusations'){if(!state.me.host||!state.canFinalizeAccusations)return;title='Finish without the missing accusations?';body=`<p>${state.players.filter(p=>!p.voteSubmitted).length} agent(s) have not accused anyone and have been out of contact for at least two minutes.</p><p>Their missing choices will count as abstentions, not correct answers or innocent arrests. A complete victory will not be possible. This ends the game and cannot be undone.</p>`;label='Finish with abstentions';}
 else if(kind==='vote'){const s=person(payload.suspectId);if(!s||state.phase!=='accusation'||state.me.vote)return;title=`Accuse ${s.name}?`;body='<p>Your accusation is private and cannot be changed. An innocent person you accuse will also be arrested.</p>';label='Confirm my accusation';}
 else return;
 confirmation={kind,payload:structuredClone(payload),context};confirmationTrigger=focusLocator(document.activeElement);$('#confirm-title').textContent=title;$('#confirm-body').innerHTML=body;$('#confirm-accept').textContent=label;$('#confirm-dialog').showModal();$('#confirm-cancel')?.focus();
}
async function confirmAction(){if(!confirmation)return false;const selected=confirmation;if(!sameContext(selected.context,uiContext(state))){closeConfirmation();notice('The round or phase changed. Review your choice again.',true);return false;}closeConfirmation();let data=selected.payload;if(['select','end'].includes(selected.kind))data={...data,round:state.round};if(selected.kind==='advance')data={round:state.round,confirmed:true};if(['claimHost','finalizeAccusations'].includes(selected.kind))data={confirmed:true};if(selected.kind==='correlate')data={...data,round:state.round,expectedPhase:state.phase};const success=await act(selected.kind,data);if(success&&selected.kind==='select'){historyRound=null;navigate('interrogate');}return success;}
function trapDialogFocus(event){if(event.key!=='Tab')return;const controls=[...$('#confirm-dialog').querySelectorAll('button:not([disabled]),[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])')];const first=controls[0],last=controls.at(-1);if(!first)return;if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}
function resetSession(){clearQuestionConsent();if(state)ui.forget(state.code,state.me.id);else if(session)ui.forget(session.code,session.playerId);closeConfirmation(false);session=null;state=null;pending=null;lastVersion=-1;stage='analyse';selectedVote='';dossierId=null;historyRound=null;storage.remove('shift-session');storage.remove('shift-pending');history.replaceState(null,'',location.pathname);render();}
async function poll(){if(!session||busy||pending)return;const pollingSession=session;try{if(state&&state.phase!=='reveal'&&Date.now()-lastHeartbeat>=30000){let beat;try{beat=await fetchJson(`/api/rooms/${pollingSession.code}/actions`,{body:{id:newRequestId(),type:'heartbeat'}});}catch(error){if(error.status!==400)throw error;/* A final vote can finish the game before this heartbeat arrives. Read authoritative state below. */}lastHeartbeat=Date.now();if(session!==pollingSession||busy||pending)return;if(beat&&beat.version>lastVersion)applyState(beat);}const next=await fetchJson(`/api/rooms/${pollingSession.code}?since=${lastVersion}`);if(session!==pollingSession||busy||pending)return;if(next&&next.version>lastVersion)applyState(next);if($('#notice').dataset.network){$('#notice').textContent='';delete $('#notice').dataset.network;}}catch(error){if(session!==pollingSession||busy||pending)return;if(error.status===404||error.status===401){resetSession();notice(error.status===404?'This room has expired. Create or join another investigation.':'Your identity could not be restored. Join a new investigation.',true);}else{notice('Connection interrupted. Reconnecting…',true);$('#notice').dataset.network='1';}}}
// Browser events
document.addEventListener('focusin',()=>{focusVersion++;});
$('#confirm-cancel').addEventListener('click',()=>closeConfirmation());
$('#confirm-accept').addEventListener('click',()=>confirmAction());
$('#confirm-dialog').addEventListener('keydown',trapDialogFocus);
$('#confirm-dialog').addEventListener('cancel',event=>{event.preventDefault();closeConfirmation();});
document.addEventListener('click',async event=>{
 const b=event.target.closest('button');if(!b)return;
 if(b.dataset.stage){navigate(b.dataset.stage);return;}if(b.dataset.entry){entryMode=b.dataset.entry;render();return;}
 const action=b.dataset.action;if(!action)return;
 if(action==='retry'){await runPending();return;}if(action==='copy'){try{await navigator.clipboard.writeText(state.code);notice('Room code copied. Share this server address as well.');}catch{notice(`Room code: ${state.code}. Select and copy it manually.`);}return;}
 if(action==='reset'){resetSession();return;}if(action==='dossier'){saveDrafts();dossierId=b.dataset.id;render();$('#dossier-detail')?.focus();return;}
 if(action==='topic'){const field=$('#question');if(field){field.value=topicLabels[b.dataset.id];ui.writeDraft(uiContext(state),'questionTopic','');if($('#question-topic'))$('#question-topic').value='';if($('#topic-hint'))$('#topic-hint').textContent=topicHint(field.value);ui.writeDraft(uiContext(state),'question',field.value);syncQuestionConsent();$('#question-count').textContent=field.value.length;field.focus();}return;}
 if(busy||pending)return;
 if(action==='start')await act('start');
 if(action==='review-topic')reviewTopic(b.dataset.id);
 if(['select','share','end','advance','claimHost','finalizeAccusations'].includes(action))openConfirmation(action,action==='select'?{suspectId:b.dataset.id}:action==='share'?{messageId:b.dataset.id}:{});
});
document.addEventListener('submit',async event=>{
 event.preventDefault();if(busy||pending)return;const form=event.target,data=Object.fromEntries(new FormData(form));
 if(form.id==='create-form')await command('/api/rooms',{...data,id:newRequestId()},true);
 if(form.id==='join-form')await command(`/api/rooms/${data.code.trim().toUpperCase()}/join`,{name:data.name,id:newRequestId()},true);
 if(form.id==='question-form'){const topic=Object.hasOwn(topicLabels,data.topic)?data.topic:Object.entries(topicLabels).find(([,label])=>label===data.question.trim())?.[0];await act('ask',{question:data.question,round:state.round,...(optionalAi&&data.aiConsent==='yes'?{aiConsent:true}:{}),...(topic?{topic}:{})});}
 if(form.id==='note-form')await act('note',{text:data.text,round:state.round,expectedPhase:state.phase});
 if(form.id==='correlation-form')openConfirmation('correlate',readCorrelationForm());
 if(form.id==='vote-form')openConfirmation('vote',{suspectId:data.suspectId});
});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='suspect-search'){search=el.value;render();}if(el.id==='source-search'){saveDrafts();sourceSearch=el.value;render();}if(el.id==='question'&&$('#topic-hint'))$('#topic-hint').textContent=topicHint(el.value);if(el.name==='suspectId')selectedVote=el.value;if(el.dataset.draft){saveDrafts();syncQuestionConsent();const counter=$('#'+(el.id==='question'?'question-count':el.id==='hypothesis'?'hypothesis-count':'note-count'));if(counter)counter.textContent=el.value.length;}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='question-ai-consent'){questionConsentKey=el.checked?currentQuestionConsentKey():null;}if(el.id==='question-topic'){saveDrafts();syncQuestionConsent();if($('#topic-hint'))$('#topic-hint').textContent=topicHint($('#question')?.value??'');}if(el.id==='suspect-filter'){filter=el.value;render();}if(el.id==='interview-round'){saveDrafts();historyRound=el.value==='current'?null:Number(el.value);render();}if(['source-a','source-b','relation'].includes(el.id)){saveDrafts();if(el.id!=='relation')updateSourcePreviews();}});
document.addEventListener('error',event=>{if(event.target.matches?.('.portrait img'))event.target.remove();},true);
window.addEventListener('popstate',()=>{const value=location.hash.slice(1);navigate(STAGES.includes(value)?value:'analyse',{history:'none',focus:true});});
try{await fetchJson('/api/session',{body:{}});const catalogue=await fetchJson('/api/cases');cases=catalogue.cases;optionalAi=catalogue.dialogueMode==='optional-openai';render();if(pending)await runPending();else if(session)await poll();if(!ui.persistent)notice('Local storage is unavailable. Keep this tab open to retain your drafts.',true);}catch{notice('Server unavailable. Reload when your connection returns.',true);}
async function schedulePoll(){await poll();setTimeout(schedulePoll,(document.hidden?15000:2500)+Math.floor(Math.random()*400));}
setTimeout(schedulePoll,2500);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll();});
